#!/usr/bin/env bash
# Inject onboarding or returning-project context for /de:start.
# Three cases:
#   1. No config → inject full onboarding sequence
#   2. Config with project_type: existing → inject existing-project context
#   3. Config with project_type: new → stay silent (meta-setup handles returning)

CONFIG=".design-engineer.yaml"

if [ ! -f "$CONFIG" ]; then
  # Case 1: No config — full onboarding sequence
  cat <<'HOOK_EOF'
{"hookSpecificOutput":{"hookEventName":"UserPromptSubmit","additionalContext":"DESIGN_ENGINEER_PROJECT_STATE: new_to_plugin\n\nONBOARDING SEQUENCE — follow these steps when /de:start runs. Do not skip any step.\n\nSTEP 1: Ask ONE question (no text before it):\n  question=\"Welcome to Design Engineer Plugin. What brings you here?\"\n  header=\"Project type\"\n  options=[{label: \"New product idea\", description: \"Starting from scratch – I have an idea or a problem I want to solve\"}, {label: \"Existing project\", description: \"I already have a product, codebase, or designs – I want to improve, review, or add features\"}]\n\nAfter receiving the answer, follow the matching path:\n\nPATH A — \"New product idea\":\n  Load the meta-setup skill and proceed to its Step 2 (Detect Environment). The meta-setup skill handles the full new-product setup.\n\nPATH B — \"Existing project\":\n  Continue with steps 2–5 below. Do not skip any.\n\n  STEP 2: Ask goal question:\n    question=\"What would you like to do with your existing project?\"\n    header=\"Goal\"\n    options=[{label: \"Review what I have\", description: \"Audit quality, find UX issues, check accessibility\"}, {label: \"Implement from Figma\", description: \"I have designs ready to turn into code\"}, {label: \"Design a new feature\", description: \"Start the design thinking process for something new\"}, {label: \"Set up the dev workflow\", description: \"Configure AI-assisted development for this project\"}]\n\n  STEP 3: Ask mode question:\n    question=\"How do you want to work?\"\n    header=\"Mode\"\n    options=[{label: \"Guided mode (Recommended)\", description: \"Step by step – I share my thinking, ask questions, and you review each step\"}, {label: \"God mode\", description: \"Mostly automated – I plan and execute with minimal interruption. Faster but less control.\"}]\n\n  STEP 4: Run setup silently, then ask status line:\n    a) Run detect-environment.sh from the meta-setup skill scripts directory. Do NOT launch Explore agents or scan the project separately — the script handles all detection.\n    b) Create .design-engineer.yaml with project_type, selected mode, goal, and detected environment\n    c) Scaffold docs/design/ folder via init-project-structure.sh from meta-setup scripts\n    d) Show brief environment results in plain language. Only show what matters for the user's goal — tech stack and tool connections. Do NOT show Git status, CLAUDE.md status, or other developer internals.\n    e) Ask status line question. Do NOT use the built-in statusline-setup agent. Instead copy the script manually: cp ${CLAUDE_PLUGIN_ROOT}/hooks/de-statusline.js ~/.claude/hooks/de-statusline.js, then read ~/.claude/settings.json and set statusLine to {\"type\": \"command\", \"command\": \"node ~/.claude/hooks/de-statusline.js\"}, write back.\n       question=\"Would you like to install the status line?\"\n       header=\"Status line\"\n       options=[{label: \"Yes (Recommended)\", description: \"Shows model, usage limits, context bar, and pipeline progress below every prompt\"}, {label: \"No\", description: \"Skip – re-run /de:start later to install\"}]\n\n  STEP 5: Say \"You're all set. Let's get started.\" then load the /de: command matching the goal:\n    Review what I have -> /de:review\n    Implement from Figma -> /de:dev\n    Design a new feature -> /de:design\n    Set up the dev workflow -> /de:dev\n\nIf user selected \"New product idea\" in step 1, skip steps 2-5 and load the meta-setup skill at Step 2 (Detect Environment) instead."}}
HOOK_EOF

elif grep -q "project_type: existing" "$CONFIG" 2>/dev/null; then
  # Case 2: Config exists with project_type: existing — show capabilities via AskUserQuestion
  cat <<'HOOK_EOF'
{"hookSpecificOutput":{"hookEventName":"UserPromptSubmit","additionalContext":"DESIGN_ENGINEER_PROJECT_STATE: existing_project\n\nThis project has the Design Engineer Plugin configured as an existing project. When /de:start runs:\n\n1. Do NOT show returning-pipeline state or resume information.\n2. Show a brief welcome and present available commands via AskUserQuestion:\n   question=\"What would you like to do?\"\n   header=\"Goal\"\n   options=[{label: \"Review what I have\", description: \"Audit quality, find UX issues, check accessibility\"}, {label: \"Implement from Figma\", description: \"I have designs ready to turn into code\"}, {label: \"Design a new feature\", description: \"Start the design thinking process\"}, {label: \"Set up the dev workflow\", description: \"Configure AI-assisted development\"}]\n3. After the user answers, load the matching /de: command directly.\n4. Do NOT mention config files, project types, or detection state."}}
HOOK_EOF

fi
# Case 3: Config exists with project_type: new (or other) — stay silent, meta-setup handles it
